CREATE UNIQUE INDEX atmpt_ans_dtl_t_atmpt_id_qstn_id_key ON public.atmpt_ans_dtl_t USING btree (atmpt_id, qstn_id);

CREATE UNIQUE INDEX atmpt_dtl_t_asmt_id_user_id_atmpt_no_key ON public.atmpt_dtl_t USING btree (asmt_id, user_id, atmpt_no);

CREATE INDEX atmpt_dtl_t_college_id_idx ON public.atmpt_dtl_t USING btree (college_id);

CREATE INDEX atmpt_dtl_t_status_cd_expires_ts_idx ON public.atmpt_dtl_t USING btree (status_cd, expires_ts);

CREATE INDEX atmpt_dtl_t_user_id_idx ON public.atmpt_dtl_t USING btree (user_id);

-- Foreign keys
ALTER TABLE ONLY public.atmpt_ans_dtl_t
    ADD CONSTRAINT atmpt_ans_dtl_t_atmpt_id_fkey FOREIGN KEY (atmpt_id) REFERENCES public.atmpt_dtl_t(atmpt_id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY public.atmpt_ans_dtl_t
